#include <iostream>
int main() {
    constexpr int secret = 7;
    int guess = 0;
    while (guess != secret) {
        std::cout << "Guess (1-10): ";
        if (!(std::cin >> guess)) { std::cerr << "Please enter an integer.\n"; return 1; }
        if (guess < secret) std::cout << "Too low\n";
        else if (guess > secret) std::cout << "Too high\n";
    }
    std::cout << "Correct!\n";
}
